import { useState, useEffect } from 'react';
import axios from 'axios';

const UserManager = () => {
  const [users, setUsers] = useState([]);
  const [roles, setRoles] = useState([]);
  const [editingId, setEditingId] = useState(null);
  const [form, setForm] = useState({
    surname: '',
    name: '',
    patronymic: '',
    phone: '',
    password: '',
    roleId: '',
    vkId: '',
  });
  const [error, setError] = useState('');          // общая ошибка (например, сеть)
  const [fieldErrors, setFieldErrors] = useState({}); // ошибки конкретных полей

  // Загрузка пользователей и списка ролей
  const fetchUsers = async () => {
    try {
      const res = await axios.get('/api/admin/users');
      setUsers(res.data);
    } catch {
      setError('Ошибка загрузки пользователей');
    }
  };

  const fetchRoles = async () => {
    try {
      const res = await axios.get('/api/admin/roles');
      setRoles(res.data);
    } catch {
      setError('Ошибка загрузки ролей');
    }
  };

  useEffect(() => {
    fetchUsers();
    fetchRoles();
  }, []);

  const resetForm = () => {
    setForm({
      surname: '',
      name: '',
      patronymic: '',
      phone: '',
      password: '',
      roleId: '',
      vkId: '',
    });
    setEditingId(null);
    setError('');
    setFieldErrors({});
  };

  // Валидация полей
  const validate = () => {
    const errors = {};

    if (!form.surname || form.surname.trim().length < 2) {
      errors.surname = 'Фамилия должна содержать минимум 2 символа';
    }
    if (!form.name || form.name.trim().length < 2) {
      errors.name = 'Имя должно содержать минимум 2 символа';
    }
    if (!form.phone || form.phone.trim().length === 0) {
      errors.phone = 'Телефон обязателен';
    }
    if (!form.roleId) {
      errors.roleId = 'Роль обязательна';
    }

    // Пароль: обязателен при создании нового пользователя; если редактируем и поле пустое – ок,
    // но если введён – минимум 6 символов.
    if (!editingId && (!form.password || form.password.length < 6)) {
      errors.password = 'Пароль обязателен и должен быть минимум 6 символов';
    } else if (form.password.length > 0 && form.password.length < 6) {
      errors.password = 'Пароль должен содержать минимум 6 символов';
    }

    // Если роль = employee (id роли "employee" найти в списке), то vkId обязателен
    const employeeRole = roles.find(r => r.name === 'employee');
    if (employeeRole && form.roleId == employeeRole.id && (!form.vkId || form.vkId.toString().trim() === '')) {
      errors.vkId = 'ID ВКонтакте обязателен для сотрудника';
    }

    setFieldErrors(errors);
    return Object.keys(errors).length === 0;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    if (!validate()) return;

    try {
      if (editingId) {
        await axios.put(`/api/admin/users/${editingId}`, form);
      } else {
        await axios.post('/api/admin/users', form);
      }
      resetForm();
      fetchUsers();
    } catch (err) {
      setError(err.response?.data?.message || 'Ошибка сохранения');
    }
  };

  const handleEdit = (user) => {
    setEditingId(user.id);
    setForm({
      surname: user.surname,
      name: user.name,
      patronymic: user.patronymic || '',
      phone: user.phone,
      password: '',          // пароль не подтягиваем
      roleId: user.role?.id || user.roleId,
      vkId: user.vkId || '',
    });
    setFieldErrors({});
  };

  const handleDelete = async (id) => {
    if (window.confirm('Удалить пользователя?')) {
      await axios.delete(`/api/admin/users/${id}`);
      fetchUsers();
    }
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setForm(prev => ({ ...prev, [name]: value }));
    // Убираем ошибку поля при редактировании
    if (fieldErrors[name]) {
      setFieldErrors(prev => ({ ...prev, [name]: undefined }));
    }
  };

  const employeeRole = roles.find(r => r.name === 'employee');
  const showVkId = employeeRole && form.roleId == employeeRole.id;

  return (
    <div className="user-manager">
      <h2>Управление пользователями</h2>
      {error && <div className="error-message">{error}</div>}
      <form onSubmit={handleSubmit} className="user-form">
        <div className="form-group">
          <input
            name="surname"
            placeholder="Фамилия"
            value={form.surname}
            onChange={handleChange}
            required
          />
          {fieldErrors.surname && <span className="field-error">{fieldErrors.surname}</span>}
        </div>

        <div className="form-group">
          <input
            name="name"
            placeholder="Имя"
            value={form.name}
            onChange={handleChange}
            required
          />
          {fieldErrors.name && <span className="field-error">{fieldErrors.name}</span>}
        </div>

        <div className="form-group">
          <input
            name="patronymic"
            placeholder="Отчество"
            value={form.patronymic}
            onChange={handleChange}
          />
          {/* Отчество не валидируем */}
        </div>

        <div className="form-group">
          <input
            name="phone"
            placeholder="Телефон"
            value={form.phone}
            onChange={handleChange}
            required
          />
          {fieldErrors.phone && <span className="field-error">{fieldErrors.phone}</span>}
        </div>

        <div className="form-group">
          <input
            name="password"
            type="password"
            placeholder={editingId ? 'Новый пароль (необязательно)' : 'Пароль'}
            value={form.password}
            onChange={handleChange}
            required={!editingId}
          />
          {fieldErrors.password && <span className="field-error">{fieldErrors.password}</span>}
        </div>

        <div className="form-group">
          <select name="roleId" value={form.roleId} onChange={handleChange} required>
            <option value="">Выберите роль</option>
            {roles.map(role => (
              <option key={role.id} value={role.id}>{role.name}</option>
            ))}
          </select>
          {fieldErrors.roleId && <span className="field-error">{fieldErrors.roleId}</span>}
        </div>

        {showVkId && (
          <div className="form-group">
            <input
              name="vkId"
              type="number"
              placeholder="ID ВКонтакте"
              value={form.vkId}
              onChange={handleChange}
            />
            {fieldErrors.vkId && <span className="field-error">{fieldErrors.vkId}</span>}
          </div>
        )}

        <div className="form-buttons">
          <button type="submit">{editingId ? 'Сохранить' : 'Создать'}</button>
          {editingId && <button type="button" onClick={resetForm}>Отмена</button>}
        </div>
      </form>

      <table className="user-table">
        <thead>
          <tr>
            <th>ID</th><th>ФИО</th><th>Телефон</th><th>Роль</th><th>VK ID</th><th>Действия</th>
          </tr>
        </thead>
        <tbody>
          {users.map(u => (
            <tr key={u.id}>
              <td>{u.id}</td>
              <td>{u.surname} {u.name} {u.patronymic}</td>
              <td>{u.phone}</td>
              <td>{u.role?.name || '—'}</td>
              <td>{u.vkId || '-'}</td>
              <td>
                <button onClick={() => handleEdit(u)}>✏️</button>
                <button onClick={() => handleDelete(u.id)}>🗑️</button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default UserManager;
